package com.company.aiinterview.voice.controller; import com.company.aiinterview.voice.dto.request.TextToSpeechRequestDto; import com.company.aiinterview.voice.dto.response.*; import com.company.aiinterview.voice.service.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; @RestController @RequestMapping("/api/v1/voice") @RequiredArgsConstructor public class VoiceController { private final VoiceInterviewService vis; private final SpeechToTextService stt; private final TextToSpeechService tts; @GetMapping("/interview/{sessionId}/question/{questionId}/audio") public VoiceQuestionAudioResponseDto qa(@PathVariable Long sessionId,@PathVariable Long questionId){ return vis.generateQuestionAudio(sessionId,questionId);} @PostMapping("/interview/{sessionId}/answer/{questionId}/audio") public SpeechToTextResponseDto sa(@PathVariable Long sessionId,@PathVariable Long questionId,@RequestParam MultipartFile file){ return vis.submitVoiceAnswer(sessionId,questionId,file);} @PostMapping("/stt") public SpeechToTextResponseDto stt(@RequestParam MultipartFile file){ return stt.transcribe(file);} @PostMapping("/tts") public TextToSpeechResponseDto tts(@RequestBody TextToSpeechRequestDto request){ return tts.synthesize(request);} }
